#include "raid/json.hpp"
#include <sstream>
namespace raid{static std::string q(const std::string&s){std::string o="\"";for(char c:s){if(c=='"'||c=='\\'){o+='\\';o+=c;}else o+=c;}return o+"\"";}std::string json(const Result&r){std::ostringstream o;o<<"{\"status\":"<<q(r.status)<<",\"level\":"<<q(name(r.layout.level))<<",\"stripe_sectors\":"<<r.layout.stripe_sectors<<",\"logical_size\":"<<r.layout.logical_size<<",\"score\":"<<r.layout.score<<",\"members\":[";for(size_t i=0;i<r.members.size();i++){if(i)o<<",";auto&m=r.members[i];o<<"{\"index\":"<<m.index<<",\"path\":"<<q(m.path)<<",\"size\":"<<m.size<<",\"missing\":"<<(m.missing?"true":"false")<<"}";}o<<"],\"evidence\":[";for(size_t i=0;i<r.layout.evidence.size();i++){if(i)o<<",";o<<q(r.layout.evidence[i]);}o<<"],\"warnings\":[";for(size_t i=0;i<r.warnings.size();i++){if(i)o<<",";o<<q(r.warnings[i]);}o<<"]}";return o.str();}}
